import fs from 'fs';
import os from 'os';
import path from 'path';
import { createServer } from 'vite';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { ISOLATED_BUILD_CONFIG } from '../build.js';
import { startDevMode } from '../dev.js';
import { DevServerState } from '../DevServerState.js';
import startDevServer from '../server.js';
import { createDevServerConfig, createMockLogger } from './factories.js';
import { cardConfig } from './fixtures/extensionConfig.js';
vi.mock('vite', () => ({
    createServer: vi.fn(() => ({
        name: 'vite-dev-server',
    })),
}));
vi.mock('../server', () => ({
    default: vi.fn(() => ({
        httpServer: {},
        shutdown: vi.fn(),
    })),
}));
vi.mock('detect-port', () => ({
    default: vi.fn((port) => {
        if (port === 7890) {
            return 1235; // Simulate port unavailable
        }
        return port;
    }),
}));
describe('dev', () => {
    let devServerState;
    let logger;
    beforeEach(() => {
        vi.clearAllMocks();
        logger = createMockLogger();
        devServerState = new DevServerState(createDevServerConfig(logger));
    });
    describe('startDevMode', () => {
        it('should throw an error if extensionConfig is undefined', async () => {
            // @ts-expect-error Causing an error on purpose
            await expect(startDevMode(undefined)).rejects.toThrow(/^Unable to determine which extension to run/);
        });
        it('should throw an error if the express port is in use', async () => {
            const badPort = new DevServerState(createDevServerConfig(logger, { expressPort: 7890 }));
            await expect(startDevMode(badPort)).rejects.toThrow(/^Unable to start because port 7890 is already in use/);
        });
        it('should call vite createServer', async () => {
            await startDevMode(devServerState);
            expect(createServer).toHaveBeenCalledTimes(1);
            expect(createServer).toHaveBeenCalledWith(expect.objectContaining({
                appType: 'custom',
                mode: 'development',
                ...ISOLATED_BUILD_CONFIG,
                server: expect.objectContaining({
                    middlewareMode: true,
                    hmr: expect.objectContaining({
                        server: null,
                    }),
                    cors: expect.objectContaining({
                        credentials: true,
                    }),
                    watch: {
                        ignored: [
                            `${devServerState.outputDir}/**/*`,
                            '**/src/app/app.functions/**/*',
                            '**/app.json',
                            '**/package.json',
                            '**/package-lock.json',
                        ],
                    },
                }),
                clearScreen: false,
                logLevel: 'silent',
            }));
        });
        it('should call startDevServer', async () => {
            await startDevMode(devServerState);
            expect(startDevServer).toHaveBeenCalledTimes(1);
            expect(startDevServer).toHaveBeenCalledWith({
                devServerState,
                viteDevServer: { name: 'vite-dev-server' },
            });
        });
    });
    describe('config file warnings', () => {
        let tmpDir;
        beforeEach(() => {
            tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'uie-dev-spec-'));
        });
        afterEach(() => {
            fs.rmSync(tmpDir, { recursive: true, force: true });
        });
        function makeStateWithDirs(appPath, extensionPath) {
            const cfg = {
                ...cardConfig,
                path: appPath,
                extensionPath,
            };
            return new DevServerState(createDevServerConfig(logger, { extensionConfigs: [cfg] }));
        }
        it('warns when a config file is present in the extension directory', async () => {
            const extDir = path.join(tmpDir, 'ext');
            fs.mkdirSync(extDir);
            fs.writeFileSync(path.join(extDir, 'vite.config.ts'), '');
            const state = makeStateWithDirs(tmpDir, extDir);
            await startDevMode(state);
            expect(logger.warn).toHaveBeenCalledWith(expect.stringContaining('Vite config found in extension source'));
        });
        it('warns when a config file is present in the app root (appPath)', async () => {
            fs.writeFileSync(path.join(tmpDir, 'postcss.config.js'), '');
            const extDir = path.join(tmpDir, 'ext');
            fs.mkdirSync(extDir);
            const state = makeStateWithDirs(tmpDir, extDir);
            await startDevMode(state);
            expect(logger.warn).toHaveBeenCalledWith(expect.stringContaining('PostCSS config found in extension source'));
        });
        it('warns for each extension directory separately', async () => {
            const extDirA = path.join(tmpDir, 'extA');
            const extDirB = path.join(tmpDir, 'extB');
            fs.mkdirSync(extDirA);
            fs.mkdirSync(extDirB);
            fs.writeFileSync(path.join(extDirA, '.env'), '');
            fs.writeFileSync(path.join(extDirB, '.env'), '');
            const cfgA = { ...cardConfig, path: tmpDir, extensionPath: extDirA };
            const cfgB = { ...cardConfig, path: tmpDir, extensionPath: extDirB };
            const state = new DevServerState(createDevServerConfig(logger, { extensionConfigs: [cfgA, cfgB] }));
            await startDevMode(state);
            const warnCalls = vi.mocked(logger.warn).mock.calls.map((c) => c[0]);
            const envWarns = warnCalls.filter((msg) => msg.includes('Environment file found in extension source'));
            expect(envWarns.length).toBeGreaterThanOrEqual(2);
        });
        it('does not warn when directories are clean', async () => {
            const extDir = path.join(tmpDir, 'ext');
            fs.mkdirSync(extDir);
            const state = makeStateWithDirs(tmpDir, extDir);
            await startDevMode(state);
            expect(logger.warn).not.toHaveBeenCalledWith(expect.stringContaining('found in extension source'));
        });
    });
});
